// Joins the ~40 data/engine scripts into one file, js/bundle.js, so the page loads in a single request.
// Re-run after every change to any of these files:   node tools/bundle.js
// (js/app.js stays separate: it is the interface, not content.)
// Exports sources() so the tests can load exactly the same files in the same order.
const fs = require("fs"), path = require("path");
const root = path.join(__dirname, "..");
const js = path.join(root, "js");

function sources() {
  const all = fs.readdirSync(js);
  const pick = (re) => all.filter((f) => re.test(f)).sort((a, b) => a.localeCompare(b, "en", { numeric: true }));
  return [
    "characters.js",
    "training-pack.js", ...pick(/^training-pack-\d+\.js$/),
    // character files: the original loading order (matters for how packs merge)
    "c-bilge.js", "c-rumi.js", "c-timur.js", "c-leonidas.js", "c-hannibal.js", "c-attila.js", "c-joan.js", "c-napoleon.js", "c-nietzsche.js", "c-tesla.js",
    ...pick(/^train-.*\.js$/),
    ...pick(/^tr-.*\.js$/),          // Turkish lines (one file per member)
    ...pick(/^tr2-.*\.js$/),         // Turkish answers about himself and opinions of the others (extend tr-<id>.js)
    ...pick(/^story-.*\.js$/),      // more stories from each life
    ...pick(/^combo-.*\.js$/),      // lines written for one feeling + one topic together
    "engine.js", "campaigns.js", "campaigns-2.js",
  ];
}

function build() {
  const files = sources();
  const missing = files.filter((f) => !fs.existsSync(path.join(js, f)));
  if (missing.length) { console.error("missing:", missing.join(", ")); process.exit(1); }
  const out = "/* GENERATED by tools/bundle.js from " + files.length + " files. Do not edit: edit the source files and re-run `node tools/bundle.js`. */\n" +
    files.map((f) => `\n/* ===== ${f} ===== */\n` + fs.readFileSync(path.join(js, f), "utf8").replace(/\s+$/, "") + "\n;").join("\n");
  fs.writeFileSync(path.join(js, "bundle.js"), out);
  console.log(`js/bundle.js: ${files.length} files, ${(out.length / 1024).toFixed(0)} KB`);
}

module.exports = { sources, build };
if (require.main === module) build();
